begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('ae030000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-admission-'||n||'@example.test',now()from generate_series(1,4)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,4)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic admission owner');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Synthetic admission practice');
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(31),pg_temp.id(21),'Synthetic admission clinic','Etc/UTC');
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('edition','synthetic_preview','synthetic_fixture',true,'approved',true,'role','owner'))::text,true)$$;
select is((select count(*)::integer from public.doctor_candidate_admissions),0,'migration seeds no real or synthetic actor admission');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.doctor_candidate_admissions'::regclass),'admissions use forced RLS');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.doctor_candidate_revocations'::regclass),'revocations use forced RLS');
select ok(not has_table_privilege('authenticated','public.doctor_candidate_admissions','SELECT'),'client cannot enumerate test actors');
select ok(not has_table_privilege('authenticated','public.doctor_candidate_admissions','INSERT'),'owner browser cannot self-admit');
select ok(not has_table_privilege('service_role','public.doctor_candidate_admissions','INSERT'),'service API credentials cannot grant admission');
select ok(not has_table_privilege('authenticated','public.doctor_candidate_revocations','INSERT'),'client cannot forge operator revocation evidence');
select ok(not has_function_privilege('authenticated','doctor_private.candidate_evidence_immutable()','EXECUTE'),'trigger helper has no client execution privilege');
set local role authenticated;select pg_temp.claim(1);
select is(doctor_private.current_actor(),pg_temp.id(1),'existing explicit synthetic preview remains compatible');
reset role;
update public.doctor_edition_policy set mode='administrative_candidate',revision=2,change_reason='Synthetic admission verification';
set local role authenticated;select pg_temp.claim(1);
select throws_ok($$select doctor_private.current_actor()$$,'42501','DOCTOR_SYNTHETIC_ADMISSION_REQUIRED','fresh provider session alone never admits a candidate actor');
select throws_ok($$select public.doctor_contexts()$$,'42501','DOCTOR_SYNTHETIC_ADMISSION_REQUIRED','forged browser metadata cannot obtain contexts');
select throws_ok($$select public.doctor_team(pg_temp.id(21))$$,'42501','DOCTOR_SYNTHETIC_ADMISSION_REQUIRED','unadmitted owner cannot read team projections');
select throws_ok($$insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)values(pg_temp.id(1),'synthetic_fixture','forged-browser-approval',clock_timestamp()+interval'1 hour')$$,'42501',null,'client insert is denied by SQL authority');
reset role;
select throws_ok($$insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)values(pg_temp.id(1),'real_user','not-approved',clock_timestamp()+interval'1 hour')$$,'23514',null,'no real-user purpose exists');
select throws_ok($$insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)values(pg_temp.id(1),'synthetic_fixture','too-long',clock_timestamp()+interval'25 hours')$$,'23514',null,'synthetic admission cannot be unbounded');
insert into public.doctor_candidate_admissions(id,user_id,purpose,evidence_ref,issued_at,valid_until)values
 (pg_temp.id(41),pg_temp.id(1),'synthetic_fixture','disposable-sql:admission',clock_timestamp(),clock_timestamp()+interval'2 hours'),
 (pg_temp.id(42),pg_temp.id(2),'synthetic_fixture','disposable-sql:outsider',clock_timestamp(),clock_timestamp()+interval'2 hours'),
 (pg_temp.id(43),pg_temp.id(3),'synthetic_fixture','disposable-sql:expired',clock_timestamp()-interval'2 hours',clock_timestamp()-interval'1 hour'),
 (pg_temp.id(44),pg_temp.id(4),'synthetic_fixture','disposable-sql:not-yet-valid',clock_timestamp()+interval'1 hour',clock_timestamp()+interval'2 hours');
select is((select database_actor from public.doctor_candidate_admissions where id=pg_temp.id(41)),session_user::text,'admission retains database-role attribution');
select throws_ok($$update public.doctor_candidate_admissions set valid_until=clock_timestamp()+interval'3 hours'where id=pg_temp.id(41)$$,'42501','DOCTOR_CANDIDATE_EVIDENCE_IMMUTABLE','admission cannot be rewritten or extended in place');
select throws_ok($$delete from public.doctor_candidate_admissions where id=pg_temp.id(41)$$,'42501','DOCTOR_CANDIDATE_EVIDENCE_IMMUTABLE','grant history cannot be erased');
set local role authenticated;select pg_temp.claim(1);
select is(doctor_private.current_actor(),pg_temp.id(1),'bounded synthetic actor admission opens protected candidate requests');
select is(public.doctor_administrative_edition()->>'live_activation','false','synthetic admission cannot become live approval');
select is(public.doctor_contexts()->0->>'edition','administrative_candidate','admitted context remains the restricted candidate');
select is(jsonb_array_length(public.doctor_team(pg_temp.id(21))->'available_capabilities'),10,'admitted owner still receives only effective permissions');
select throws_ok($$select public.doctor_patient_documents(pg_temp.id(21),pg_temp.id(31),pg_temp.id(51))$$,'42501','DOCTOR_ACCESS_DENIED','synthetic actor admission does not grant excluded documents');
select pg_temp.claim(2);
select is(doctor_private.current_actor(),pg_temp.id(2),'independent synthetic actor can authenticate');
select is(jsonb_array_length(public.doctor_contexts()),0,'actor admission does not invent tenant membership');
select throws_ok($$select public.doctor_team(pg_temp.id(21))$$,'42501','DOCTOR_ACCESS_DENIED','admission never bypasses another doctor tenant');
select pg_temp.claim(3);
select throws_ok($$select doctor_private.current_actor()$$,'42501','DOCTOR_SYNTHETIC_ADMISSION_REQUIRED','expired synthetic admission is denied');
select pg_temp.claim(4);
select throws_ok($$select doctor_private.current_actor()$$,'42501','DOCTOR_SYNTHETIC_ADMISSION_REQUIRED','future admission does not activate early');
reset role;
insert into public.doctor_candidate_revocations(admission_id,reason)values(pg_temp.id(41),'operator_revoke');
select throws_ok($$delete from public.doctor_candidate_revocations where admission_id=pg_temp.id(41)$$,'42501','DOCTOR_CANDIDATE_EVIDENCE_IMMUTABLE','revocation cannot be removed to replay approval');
set local role authenticated;select pg_temp.claim(1);
select throws_ok($$select doctor_private.current_actor()$$,'42501','DOCTOR_SYNTHETIC_ADMISSION_REQUIRED','revoked synthetic actor cannot reuse a still-valid provider session');
reset role;
update auth.sessions set not_after=clock_timestamp()-interval'1 second'where id=pg_temp.id(12);
set local role authenticated;select pg_temp.claim(2);
select throws_ok($$select doctor_private.current_actor()$$,'42501','DOCTOR_AUTH_REQUIRED','admission does not bypass a revoked provider session');
reset role;
select is((select provolatile::text from pg_proc where oid='doctor_private.current_actor()'::regprocedure),'v','authority is freshly checked after lock waits');
select * from finish();rollback;
